namespace sv_8c85dd6f72b24f0bbd7fb35c59319393.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// Interactive components subscribe to <see cref="OnThemeChanged"/> to
/// react when any component calls <see cref="SetTheme"/> or <see cref="SetAccentColor"/>.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnThemeChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnThemeChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnThemeChanged?.Invoke();
    }
}

