@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDocument();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeToDocument();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        await JS.InvokeVoidAsync("ThemeInterop.applyTheme",
            ThemeService.Theme.ToString().ToLowerInvariant(),
            ThemeService.AccentColor);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="theme-toggle d-inline-flex align-items-center gap-2">
    <button class="btn btn-sm @ButtonClass" @onclick="CycleTheme" title="Toggle theme">
        @GetThemeIcon()
    </button>
</div>

@code {
    private string ButtonClass => ThemeService.Theme switch
    {
        ThemeMode.Dark => "btn-outline-light",
        _ => "btn-outline-dark"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _ => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    private async void HandleThemeChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <button class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-secondary")"
                        @onclick="() => ThemeService.SetTheme(mode)">
                    @GetIcon(mode) @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentChanged"
                   title="Choose accent color" />
            <span style="color: @ThemeService.AccentColor; font-weight: bold;">
                @ThemeService.AccentColor
            </span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeService.Theme</strong><br />
            Accent color:
            <span class="badge" style="background-color: @ThemeService.AccentColor;">
                @ThemeService.AccentColor
            </span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnThemeChanged += HandleThemeChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private static string GetIcon(ThemeMode mode) => mode switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    private async void HandleThemeChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

window.ThemeInterop = {
    applyTheme: function (theme, accentColor) {
        const html = document.documentElement;

        html.removeAttribute('data-bs-theme');

        if (theme === 'light') {
            html.setAttribute('data-bs-theme', 'light');
        } else if (theme === 'dark') {
            html.setAttribute('data-bs-theme', 'dark');
        }
        // 'system' — let the browser/OS preference apply (no data-bs-theme attr)

        if (accentColor) {
            html.style.setProperty('--app-accent-color', accentColor);
        }
    }
};

