    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    private async void HandleThemeChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnThemeChanged -= HandleThemeChanged;
    }
}

