window.ThemeInterop = {
    applyTheme: function (theme, accentColor) {
        const html = document.documentElement;

        html.removeAttribute('data-bs-theme');

        if (theme === 'light') {
            html.setAttribute('data-bs-theme', 'light');
        } else if (theme === 'dark') {
            html.setAttribute('data-bs-theme', 'dark');
        }
        // 'system' — let the browser/OS preference apply (no data-bs-theme attr)

        if (accentColor) {
            html.style.setProperty('--app-accent-color', accentColor);
        }
    }
};

